import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as r,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const x=JSON.parse('{"title":"Codex IDE 扩展","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/codex/codex-ide.md","filePath":"zh/products/ai-coding/codex/codex-ide.md","lastUpdated":1787107158000}'),d={name:"zh/products/ai-coding/codex/codex-ide.md"};function n(l,e,i,c,h,s){return r(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="codex-ide-扩展" tabindex="-1">Codex IDE 扩展 <a class="header-anchor" href="#codex-ide-扩展" aria-label="Permalink to &quot;Codex IDE 扩展&quot;">​</a></h1><blockquote><p>这是一份<strong>教程</strong>——装扩展，把已经打开的文件带进提示词，在源码旁边审 diff。IDE 是 Codex 的一个入口，和 CLI 共用 <code>AGENTS.md</code>、沙箱、审批。</p><p>官方落地页：<a href="https://learn.chatgpt.com/codex/ide" target="_blank" rel="noreferrer">learn.chatgpt.com/codex/ide</a>。文档：<a href="https://learn.chatgpt.com/docs/codex/ide" target="_blank" rel="noreferrer">IDE extension</a>。</p></blockquote><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需要</th><th>要求</th></tr></thead><tbody><tr><td>账号</td><td>含 Codex 的 ChatGPT 套餐</td></tr><tr><td>编辑器</td><td>VS Code、Cursor、Windsurf、VS Code Insiders、Xcode 或 JetBrains IDE</td></tr><tr><td>仓库</td><td>一个你已经熟悉的项目目录</td></tr></tbody></table><p><strong>学习目标</strong>：在编辑器里装好 / 打开 Codex；第一次对话就带上当前文件；原地审 focused diff；长任务交给 Cloud 而不离开编辑器。</p><p><strong>非目标</strong>：CLI 安装（<a href="./codex-cli.html">CLI</a>）；Cloud 环境（<a href="./codex-cloud.html">Cloud</a>）；桌面 Chat / Work / Codex 切换（<a href="./codex-ai.html">产品线</a>、<a href="./chatgpt-work.html">Work</a>）。</p><h2 id="ide-扩展是什么-不是什么" tabindex="-1">IDE 扩展是什么，不是什么 <a class="header-anchor" href="#ide-扩展是什么-不是什么" aria-label="Permalink to &quot;IDE 扩展是什么，不是什么&quot;">​</a></h2><p>扩展把 Codex 放在<strong>代码旁边</strong>。打开的文件、当前选区、最近会话进 composer。你在源码旁边读短摘要和 focused diff。</p><p>它<strong>不是</strong>：</p><ul><li>另一套 Agent。还是 <code>~/.codex/config.toml</code> 和同一份 <code>AGENTS.md</code>。</li><li>桌面 Codex。桌面 Codex 在 <a href="https://learn.chatgpt.com/docs/app" target="_blank" rel="noreferrer">ChatGPT 桌面应用</a> 里：可视化 diff、PR 侧栏、多仓库、Computer Use。地图在 <a href="./codex-ai.html">产品线</a>，这里不重复整页。</li><li>CI 里 <code>codex exec</code> 的替代品。</li></ul><p>任务锚在当前文件 / 选区 → IDE。要脚本化 → CLI。合上电脑也要跑 → <a href="./codex-cloud.html">Cloud</a>。</p><h2 id="第-1-步-—-安装或启用" tabindex="-1">第 1 步 — 安装或启用 <a class="header-anchor" href="#第-1-步-—-安装或启用" aria-label="Permalink to &quot;第 1 步 — 安装或启用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>编辑器</th><th>怎么装</th></tr></thead><tbody><tr><td>Visual Studio Code</td><td><a href="https://marketplace.visualstudio.com/items?itemName=openai.chatgpt" target="_blank" rel="noreferrer">openai.chatgpt</a> 或 <code>vscode:extension/openai.chatgpt</code></td></tr><tr><td>Cursor</td><td><code>cursor:extension/openai.chatgpt</code></td></tr><tr><td>Windsurf</td><td><code>windsurf:extension/openai.chatgpt</code></td></tr><tr><td>VS Code Insiders</td><td>同一个 Marketplace 项</td></tr><tr><td>Xcode</td><td><a href="https://developer.apple.com/documentation/Xcode/setting-up-coding-intelligence" target="_blank" rel="noreferrer">Setting up coding intelligence</a>；选 Codex</td></tr><tr><td>JetBrains IDE</td><td><a href="https://www.jetbrains.com/help/ai-assistant/codex-agent.html" target="_blank" rel="noreferrer">AI Assistant 里的 Codex</a>；打开 AI Chat 选 Codex</td></tr></tbody></table><p>用和 CLI 同一套 ChatGPT 账号登录。</p><h2 id="第-2-步-—-打开-codex" tabindex="-1">第 2 步 — 打开 Codex <a class="header-anchor" href="#第-2-步-—-打开-codex" aria-label="Permalink to &quot;第 2 步 — 打开 Codex&quot;">​</a></h2><p><strong>VS Code / Cursor / Windsurf：</strong> 点 Codex 图标。看不见就命令面板跑 <strong>Codex: Open Codex Sidebar</strong>。</p><p><strong>Xcode：</strong> 打开 coding assistant，新会话，选 Codex。</p><p><strong>JetBrains：</strong> 打开 AI Chat，选 Codex。</p><h2 id="第-3-步-—-第一次对话-带上编辑器上下文" tabindex="-1">第 3 步 — 第一次对话，带上编辑器上下文 <a class="header-anchor" href="#第-3-步-—-第一次对话-带上编辑器上下文" aria-label="Permalink to &quot;第 3 步 — 第一次对话，带上编辑器上下文&quot;">​</a></h2><p>打开熟悉的项目。让它解释或做小改动。任务前后做 Git checkpoint，方便回滚。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@src/auth/session.ts Explain how session refresh works, then add a test for</span></span>
<span class="line"><span>the expired-token path only. Do not change the cookie format.</span></span></code></pre></div><p>从 composer 附上打开的文件或选区，不要复述问题。官方：<a href="https://learn.chatgpt.com/docs/prompting#use-editor-context" target="_blank" rel="noreferrer">Use editor context</a>。</p><h2 id="第-4-步-—-在源码旁边审" tabindex="-1">第 4 步 — 在源码旁边审 <a class="header-anchor" href="#第-4-步-—-在源码旁边审" aria-label="Permalink to &quot;第 4 步 — 在源码旁边审&quot;">​</a></h2><p>读摘要。看改动行。只留你要的。同一条会话里追问。没打开过的跨文件大改不要收。</p><h2 id="第-5-步-—-任务变大就委派" tabindex="-1">第 5 步 — 任务变大就委派 <a class="header-anchor" href="#第-5-步-—-任务变大就委派" aria-label="Permalink to &quot;第 5 步 — 任务变大就委派&quot;">​</a></h2><p>短迭代留在本地。需要更长时间就接到 Codex web，送进 <a href="./codex-cloud.html">Cloud</a>。编辑器里的会话还在，回来审结果。</p><p>官方：<a href="https://learn.chatgpt.com/docs/cloud#delegate-from-the-ide-extension" target="_blank" rel="noreferrer">从 IDE 委派</a>。</p><h2 id="什么时候用-ide" tabindex="-1">什么时候用 IDE <a class="header-anchor" href="#什么时候用-ide" aria-label="Permalink to &quot;什么时候用 IDE&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>为什么</th></tr></thead><tbody><tr><td>小范围改动</td><td>相关文件和 Codex 同一视图</td></tr><tr><td>读陌生代码</td><td>问已经打开的符号</td></tr><tr><td>原地审</td><td>diff 贴着源码</td></tr><tr><td>更大的任务</td><td>从 IDE 开 Cloud，回来看结果</td></tr></tbody></table><p>命令和设置：<a href="https://learn.chatgpt.com/docs/developer-commands?surface=ide" target="_blank" rel="noreferrer">IDE commands</a>、<a href="https://learn.chatgpt.com/docs/developer-settings?surface=ide" target="_blank" rel="noreferrer">IDE settings</a>。文档带 <code>?surface=ide</code>——页面像在讲 CLI 时，先看 surface。</p><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><table tabindex="0"><thead><tr><th>陷阱</th><th>结果</th><th>改做</th></tr></thead><tbody><tr><td>描述文件而不附上</td><td>改错模块</td><td>点名打开的文件或选区</td></tr><tr><td>当成另一套 Agent</td><td>配置 / <code>AGENTS.md</code>「没加载」</td><td>和 CLI 同一套；先信任项目</td></tr><tr><td>长任务扔在笔记本上</td><td>睡眠后会话没了</td><td>交给 <a href="./codex-cloud.html">Cloud</a></td></tr><tr><td>在这里找 PR 侧栏</td><td>那是桌面 Codex</td><td><a href="./codex-ai.html">产品线</a> · <a href="./chatgpt-work.html#桌面上-work-和-codex-怎么选">Work 与 Codex</a></td></tr></tbody></table><h2 id="实际用例" tabindex="-1">实际用例 <a class="header-anchor" href="#实际用例" aria-label="Permalink to &quot;实际用例&quot;">​</a></h2><p>打开着 <code>Button.tsx</code>，视觉测试红了。附上文件，要最小 CSS 修复，在组件旁边审 diff。如果变成设计系统 token 迁移，交给 Cloud，IDE 会话只用来审。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ol><li>带编辑器上下文的提示词 → <a href="https://learn.chatgpt.com/docs/prompting#use-editor-context" target="_blank" rel="noreferrer">Prompting</a></li><li>最佳实践 → <a href="https://learn.chatgpt.com/guides/best-practices" target="_blank" rel="noreferrer">guides/best-practices</a></li><li>长任务 → <a href="./codex-cloud.html">Cloud</a></li><li>flag 和斜杠命令 → <a href="./codex-cheatsheet.html">Cheatsheet</a></li></ol><h2 id="官方来源" tabindex="-1">官方来源 <a class="header-anchor" href="#官方来源" aria-label="Permalink to &quot;官方来源&quot;">​</a></h2><ul><li><a href="https://learn.chatgpt.com/codex/ide" target="_blank" rel="noreferrer">IDE extension（落地页）</a></li><li><a href="https://learn.chatgpt.com/docs/codex/ide" target="_blank" rel="noreferrer">IDE extension（文档）</a></li><li><a href="https://learn.chatgpt.com/docs/developer-commands?surface=ide" target="_blank" rel="noreferrer">IDE commands</a></li><li><a href="https://learn.chatgpt.com/docs/developer-settings?surface=ide" target="_blank" rel="noreferrer">IDE settings</a></li><li><a href="https://learn.chatgpt.com/docs/prompting#use-editor-context" target="_blank" rel="noreferrer">Prompting · editor context</a></li><li><a href="https://learn.chatgpt.com/docs/cloud#delegate-from-the-ide-extension" target="_blank" rel="noreferrer">从 IDE 委派</a></li><li><a href="https://marketplace.visualstudio.com/items?itemName=openai.chatgpt" target="_blank" rel="noreferrer">VS Marketplace: openai.chatgpt</a></li></ul>`,38)])])}const m=t(d,[["render",n]]);export{x as __pageData,m as default};
